// TODO: just introduce MatMxMConvert or whatever pls
func convert9[To, From constraints.Float](x [9]From) [9]To {
	return [9]To{
		To(x[0]),
		To(x[1]),
		To(x[2]),
		To(x[3]),
		To(x[4]),
		To(x[5]),
		To(x[6]),
		To(x[7]),
		To(x[8]),
	}
}

